from rich.console import Console
import os
import time
import threading
import sys

def main():
    console = Console()

    # We want to simulate a broken pipe. 
    # One way is to write to a pipe and then close the reading end.
    # However, since we are testing the Console, we can mock the file object.

    class MockFile:
        def __init__(self):
            self.closed = False
        def write(self, data):
            if self.closed:
                raise BrokenPipeError("Broken pipe")
            return len(data)
        def flush(self):
            if self.closed:
                raise BrokenPipeError("Broken pipe")
        def __getattr__(self, name):
            return lambda *args, **kwargs: None

    mock_file = MockFile()
    console.file = mock_file

    console.print("This should work")

    # Now break the pipe
    mock_file.closed = True

    try:
        console.print("This should trigger BrokenPipeError")
        # The print call might not immediately trigger _check_buffer if it's not flushed
        # but Console.print usually calls _check_buffer.
        # Let's call it explicitly to be sure.
        console._check_buffer()
    except BrokenPipeError:
        print("Caught BrokenPipeError - this is what we want to avoid!")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    else:
        print("No exception raised - success!")

if __name__ == "__main__":
    main()
